// An inline cache for a namedtuple field read (V::NTF descriptor): the low bit tags it, the next
// NTF_IDX_BITS hold the field index, the rest the CLASS_EPOCH at which it was filled (truncated:
// a cache line that has seen 2^(64-NTF_IDX_BITS-1) class changes since it was filled is treated as
// stale; a wrong hit would need that many class-attribute changes between the fill and the read).
const NTF_IDX_BITS: u32 = 24;
const NTF_IDX_MASK: usize = (1 << NTF_IDX_BITS) - 1;
#[inline]
fn ntf_ic(idx: usize, ep: u64) -> usize {
    ((ep as usize) << (NTF_IDX_BITS + 1)) | (idx << 1) | 1
}
